                "url": "https://bebbo.app/sites/default/files/styles/content_1200xh_/public/2021-12/guess-the-object-cover-picture.webp?itok=USaQnLG4",
                "name": "Guess-The-Object-cover-picture.jpg",
                "alt": "cartoon child guessing objects"
